{"code": "import os
from PIL import Image
import pathlib

data_dir = pathlib.Path("data_small/Training_Handwritten_marathi_Character_Fusion/Data_set")
corrupted_files = []

for root, dirs, files in os.walk(data_dir):
    for file in files:
        file_path = os.path.join(root, file)
        try:
            with Image.open(file_path) as img:
                img.verify()  # verify it's a valid image
        except Exception as e:
            corrupted_files.append((file_path, str(e)))
            print(f"Corrupted file: {file_path} - Error: {e}")

print(f"\nTotal corrupted files: {len(corrupted_files)}")"}

